def minCost(m, n, waitCost):
    INF = float("inf")
    dp = [INF] * n  # dp[j] holds the best cost for the current row
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dp[0] = 1  # entry cost of (0, 0), no wait before the first move
                continue
            best = dp[j]            # from above (INF in the first row)
            if j > 0 and dp[j - 1] < best:
                best = dp[j - 1]    # from the left
            cost = (i + 1) * (j + 1)
            if not (i == m - 1 and j == n - 1):
                cost += waitCost[i][j]
            dp[j] = best + cost
    return dp[n - 1]
